        window.set(big[i], (window.get(big[i]) ?? 0) + 1);
        if ((need.get(big[i]) ?? 0) >= window.get(big[i])) {
            --cnt;
        }
        while (cnt === 0) {
            if (i - j + 1 < mi) {
                mi = i - j + 1;
                k = j;
            }
            if ((need.get(big[j]) ?? 0) >= window.get(big[j])) {
                ++cnt;
            }
            window.set(big[j], window.get(big[j]) - 1);
            ++j;
        }
    }
    return k < 0 ? [] : [k, k + mi - 1];
}

